"""End-to-end document routes use fictional generated bytes and mocked AI only."""
import json
from unittest.mock import AsyncMock, Mock

from fastapi.testclient import TestClient

from backend import documents, ledger
from backend.main import app
from test_documents import extracted_row, image_bytes, mock_extraction, pdf_bytes


def upload(client, content, filename="estado-demo.pdf", account="banco"):
    return client.post("/api/imports/document-preview", data={"account": account},
                       files={"file": (filename, content)})


def two_rows():
    return [extracted_row(), extracted_row(amount_pesos="76.55", reference="REF-DEMO-002")]


def test_pending_file_account_cache_reuses_proposal_without_second_model_call(client, monkeypatch):
    parse = mock_extraction(monkeypatch, two_rows())
    content = pdf_bytes()
    response = upload(client, content)
    assert response.status_code == 200
    first = response.json()
    assert first["kind"] == "import" and first["status"] == "pending"
    assert first["payload"]["stats"]["new"] == 2
    assert first["payload"]["stats"]["expense_minor"] == 20000
    assert client.get("/api/movements").json()["total"] == 0
    assert client.get("/api/summary").json()["expense_minor"] == 0
    parse.side_effect = AssertionError("A cached document must not be sent again")
    repeated = upload(client, content, filename="mismo-ejemplo-renombrado.pdf")
    assert repeated.status_code == 200
    assert repeated.json()["id"] == first["id"]
    assert ledger.metadata()["pending"] == 1
    assert parse.await_count == 1


def test_confirmed_file_account_cache_returns_duplicates_without_second_model_call(client, monkeypatch):
    parse = mock_extraction(monkeypatch, two_rows())
    content = pdf_bytes()
    first = upload(client, content).json()
    confirmed = client.post(f"/api/proposals/{first['id']}/confirm", json={"confirm": True})
    assert confirmed.status_code == 200
    assert confirmed.json()["inserted"] == 2
    parse.side_effect = AssertionError("The confirmed extraction must be reused")
    monkeypatch.delenv("OPENAI_API_KEY", raising=False)
    repeated = upload(client, content)
    assert repeated.status_code == 200
    second = repeated.json()
    assert second["id"] != first["id"]
    assert second["status"] == "pending"
    assert second["payload"]["stats"]["duplicates"] == 2
    assert second["payload"]["stats"]["new"] == 0
    assert parse.await_count == 1
    result = client.post(f"/api/proposals/{second['id']}/confirm", json={"confirm": True})
    assert result.status_code == 200 and result.json()["inserted"] == 0
    assert ledger.metadata()["count"] == 2
    assert client.get("/api/summary").json()["expense_minor"] == 20000


def test_same_raw_document_in_another_account_is_not_cached(client, monkeypatch):
    parse = mock_extraction(monkeypatch)
    content = image_bytes()
    bank = upload(client, content, "captura-demo.png", "banco")
    cash = upload(client, content, "captura-demo.png", "efectivo")
    assert bank.status_code == cash.status_code == 200
    assert bank.json()["id"] != cash.json()["id"]
    assert bank.json()["payload"]["document"]["account"] == "banco"
    assert cash.json()["payload"]["document"]["account"] == "efectivo"
    assert parse.await_count == 2
    assert ledger.metadata()["count"] == 0


def test_edit_valid_document_row_is_audited_and_pending_until_confirm(client, monkeypatch):
    mock_extraction(monkeypatch, two_rows())
    proposal = upload(client, pdf_bytes()).json()
    original = proposal["payload"]["movements"][0]
    body = {
        "sheet": original["source_sheet"], "row": original["source_row"],
        "movement": {**original, "amount_minor": 20000, "description": "Importe ficticio revisado"},
        "reason": "Comparé importe y moneda MXN con el comprobante ficticio",
    }
    response = client.post(f"/api/proposals/{proposal['id']}/corrections", json=body)
    assert response.status_code == 200
    edited = response.json()
    assert edited["status"] == "pending"
    assert edited["payload"]["stats"]["expense_minor"] == 27655
    assert len(edited["payload"]["movements"]) == 2
    row = next(item for item in edited["payload"]["movements"] if item["source_row"] == original["source_row"])
    assert row["amount_minor"] == -20000
    assert row["account"] == "banco"
    assert row["source_hash"] == original["source_hash"]
    assert ledger.metadata()["count"] == 0
    assert client.get("/api/summary").json()["expense_minor"] == 0
    correction = edited["payload"]["corrections"][0]
    assert correction["before"]["draft"]["amount_minor"] == 12345
    assert correction["after"]["amount_minor"] == -20000
    with ledger.connection() as con:
        audit = con.execute("SELECT action,details FROM audit WHERE proposal_id=?", (proposal["id"],)).fetchall()
    assert len(audit) == 1
    assert audit[0]["action"] == "correct_proposal"
    assert json.loads(audit[0]["details"])["reason"] == body["reason"]
    assert client.post(f"/api/proposals/{proposal['id']}/confirm", json={"confirm": True}).status_code == 200
    assert client.get("/api/summary").json()["expense_minor"] == 27655
    assert client.post(f"/api/proposals/{proposal['id']}/corrections", json=body).status_code == 400


def test_document_row_edit_cannot_change_selected_account(client, monkeypatch):
    mock_extraction(monkeypatch)
    proposal = upload(client, pdf_bytes()).json()
    row = proposal["payload"]["movements"][0]
    response = client.post(f"/api/proposals/{proposal['id']}/corrections", json={
        "sheet": row["source_sheet"], "row": row["source_row"],
        "movement": {**row, "account": "efectivo", "amount_minor": abs(row["amount_minor"])},
        "reason": "Cambio de cuenta ficticio",
    })
    assert response.status_code == 400
    assert "cuenta" in response.json()["detail"].lower()
    assert ledger.get_proposal(proposal["id"])["payload"] == proposal["payload"]
    assert ledger.metadata()["count"] == 0


def test_default_demo_rejects_real_upload_before_validation_or_provider(monkeypatch):
    monkeypatch.delenv("FOLIO_DEMO", raising=False)
    validate = Mock(side_effect=AssertionError("Demo must not parse user files"))
    extract = AsyncMock(side_effect=AssertionError("Demo must not send user files"))
    monkeypatch.setattr(documents, "validate_document", validate)
    monkeypatch.setattr(documents, "extract_document", extract)
    with TestClient(app) as client:
        response = upload(client, b"must-not-be-inspected", "subida-demo.pdf")
        assert response.status_code == 400
        assert "ficticios" in response.json()["detail"]
        assert client.get("/health").json()["demo_mode"] is True
        rows = client.get("/api/movements").json()["items"]
        assert len(rows) == 18
        assert all(row["source_file"] == "movimientos-demo.json" for row in rows)
        assert all(row["reference"].startswith("REF-DEMO-") for row in rows)
    validate.assert_not_called()
    extract.assert_not_awaited()


def test_default_demo_examples_are_labeled_simulated_and_never_call_provider(monkeypatch):
    monkeypatch.delenv("FOLIO_DEMO", raising=False)
    extract = AsyncMock(side_effect=AssertionError("Examples are simulated"))
    monkeypatch.setattr(documents, "extract_document", extract)
    with TestClient(app) as client:
        before = client.get("/api/summary").json()
        for format, expected_count in [("pdf", 2), ("image", 1)]:
            response = client.post("/api/imports/document-demo", json={"format": format, "account": "banco"})
            assert response.status_code == 200
            proposal = response.json()
            payload = proposal["payload"]
            assert proposal["status"] == "pending"
            assert payload["document"]["simulated"] is True
            assert payload["document"]["model"] == "ejemplo-simulado"
            assert len(payload["movements"]) == expected_count
            assert "ficticio" in payload["filename"]
            assert all("fictici" in row["description"].lower() for row in payload["movements"])
            assert all(row["reference"].startswith("DOC-DEMO-") for row in payload["movements"])
            assert "no se leyó" in " ".join(payload["notes"])
        after = client.get("/api/summary").json()
        assert after["count"] == before["count"]
        assert after["expense_minor"] == before["expense_minor"]
    extract.assert_not_awaited()


def test_endpoint_invalid_account_and_no_key_do_not_call_provider(client, monkeypatch):
    parse = mock_extraction(monkeypatch)
    content = image_bytes()
    bad_account = upload(client, content, "captura-demo.png", "cuenta-inexistente")
    assert bad_account.status_code == 400
    assert "cuenta" in bad_account.json()["detail"]
    monkeypatch.delenv("OPENAI_API_KEY", raising=False)
    no_key = upload(client, content, "captura-demo.png")
    assert no_key.status_code == 400
    assert "clave" in no_key.json()["detail"]
    assert ledger.metadata()["count"] == ledger.metadata()["pending"] == 0
    parse.assert_not_awaited()


def test_demo_example_endpoint_is_disabled_outside_demo(client):
    response = client.post("/api/imports/document-demo", json={"format": "pdf", "account": "banco"})
    assert response.status_code == 400
    assert "modo demo" in response.json()["detail"]
    assert ledger.metadata()["pending"] == 0
